package com.bank.jvm;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.logging.*;

// Reports the active collector and runs a representative banking workload.
public class CollectorDemo {
    private static final Logger log = Logger.getLogger(CollectorDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CollectorInfo info = new CollectorInfo();
        info.printActiveCollector();

        WorkloadRunner runner = new WorkloadRunner();
        BigDecimal totalInterest = runner.calculateDailyInterest(1_000_000);
        log.info(() -> "Total interest accrued across accounts: " + totalInterest);

        info.printGcStats();
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}

// ─── Would be in Account.java in a real project ───
class Account {
    private final String accountId; private BigDecimal balance; private final BigDecimal rate;
        Account(String id, BigDecimal bal, BigDecimal rate) { accountId=id; balance=bal;
        this.rate=rate; }
    BigDecimal accrueDailyInterest() {
        // daily interest = balance * annualRate / 365
        BigDecimal interest = balance.multiply(rate)
                .divide(new BigDecimal("365"), 2, RoundingMode.HALF_UP);
        balance = balance.add(interest);
        return interest;
    }
}

// ─── Would be in WorkloadRunner.java in a real project ───
class WorkloadRunner {
    private static final Logger log = Logger.getLogger(WorkloadRunner.class.getName());

    // Creates many short-lived Account objects and sums their interest — GC pressure.
    BigDecimal calculateDailyInterest(int accountCount) {
        BigDecimal total = BigDecimal.ZERO;
        BigDecimal rate = new BigDecimal("0.065"); // 6.5% annual
        for (int i = 0; i < accountCount; i++) {
            Account acc = new Account("ACC-" + i,
                    new BigDecimal(100000 + (i % 900000)), rate);
            total = total.add(acc.accrueDailyInterest());
        }
        log.fine(() -> "Processed " + accountCount + " accounts");
        return total;
    }
}

// ─── Would be in CollectorInfo.java in a real project ───
class CollectorInfo {
    private static final Logger log = Logger.getLogger(CollectorInfo.class.getName());

    void printActiveCollector() {
        var beans = java.lang.management.ManagementFactory.getGarbageCollectorMXBeans();
        String names = beans.stream().map(java.lang.management.GarbageCollectorMXBean::getName)
                .reduce((a, b) -> a + ", " + b).orElse("unknown");
        log.info("Active GC collector(s): " + names);
    }

    void printGcStats() {
        for (var gc : java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            log.info(String.format("Collector %-26s collections=%d totalPause=%dms",
                    gc.getName(), gc.getCollectionCount(), gc.getCollectionTime()));
        }
    }
}
